import { chromium, webkit } from 'playwright';
import fs from 'node:fs';
const base='https://hearframe-grand-hello-world-v4.onrender.com/rendered/';
const marker='v5 RENDERED LIVE QA';
const results={checkedAt:new Date().toISOString(),base,marker,browsers:{},overall:'pending'};
async function waitText(page,needle,timeout=15000){const t=Date.now();let last='';while(Date.now()-t<timeout){last=(await page.locator('#status').innerText()).trim();if(last.includes(needle))return last;if(/failed:|media error|playback error/i.test(last))throw Error(last);await page.waitForTimeout(100)}throw Error(`timeout waiting for ${needle}; last=${last}`)}
async function waitDeploy(){const b=await chromium.launch({headless:true}),p=await b.newPage();try{for(let i=0;i<60;i++){try{await p.goto(base+'?wait='+Date.now(),{waitUntil:'domcontentloaded',timeout:20000});if((await p.title()).includes(marker))return}catch{}await p.waitForTimeout(3000)}throw Error('rendered route marker never appeared')}finally{await b.close()}}
async function test(type,name){const b=await type.launch({headless:true});const c=await b.newContext(name==='webkit-ipad'?{viewport:{width:1194,height:834},userAgent:'Mozilla/5.0 (iPad; CPU OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1'}:{viewport:{width:1280,height:900}});const p=await c.newPage();const rec={browser:name,steps:[],consoleErrors:[]};p.on('console',m=>{if(m.type()==='error')rec.consoleErrors.push(m.text())});p.on('pageerror',e=>rec.consoleErrors.push('pageerror: '+e.message));try{const r=await p.goto(base+'?qa='+Date.now(),{waitUntil:'networkidle',timeout:30000});rec.httpStatus=r?.status();rec.title=await p.title();if(!rec.title.includes(marker))throw Error('wrong title '+rec.title);rec.steps.push('page-loaded');rec.canPlayH264=await p.locator('#player').evaluate(v=>v.canPlayType('video/mp4; codecs="avc1.4d401f, mp4a.40.2"'));const detail=await p.locator('#audioDetails').innerText();if(!/Applied gain: HELLO/.test(detail))throw Error('metadata not rendered: '+detail);rec.audioDetails=detail;rec.steps.push('metadata-loaded');await p.locator('#hello').click();rec.hello=await waitText(p,'HELLO playback complete.',10000);rec.steps.push('hello-pass');await p.locator('#world').click();rec.world=await waitText(p,'WORLD playback complete.',10000);rec.steps.push('world-pass');await p.locator('#smooth').fill('0');if((await p.locator('#smoothValue').innerText()).trim()!=='10 ms')throw Error('natural smoothness mapping failed');rec.steps.push('natural-map-pass');await p.locator('#smooth').fill('50');if((await p.locator('#smoothValue').innerText()).trim()!=='25 ms')throw Error('balanced smoothness mapping failed');rec.steps.push('balanced-map-pass');await p.locator('#grand').click();rec.grand=await waitText(p,'Patched Hello World · 25 ms playback complete.',10000);rec.steps.push('grand-pass');await p.locator('#smooth').fill('100');if((await p.locator('#smoothValue').innerText()).trim()!=='35 ms')throw Error('smooth mapping failed');await p.locator('#grand').click();rec.grandSmooth=await waitText(p,'Patched Hello World · 35 ms playback complete.',10000);rec.steps.push('smooth-grand-pass');rec.videoSrc=await p.locator('#player').evaluate(v=>v.currentSrc);if(!rec.videoSrc.includes('/rendered/media/hello-world-smooth.mp4'))throw Error('unexpected media src '+rec.videoSrc);rec.pass=true}catch(e){rec.pass=false;rec.error=String(e?.stack||e);rec.finalStatus=await p.locator('#status').innerText().catch(()=>null)}finally{await b.close()}return rec}
let failed=false;try{await waitDeploy();for(const [name,type] of [['chromium',chromium],['webkit-ipad',webkit]]){const r=await test(type,name);results.browsers[name]=r;if(!r.pass)failed=true}}catch(e){failed=true;results.harnessError=String(e?.stack||e)}results.overall=failed?'fail':'pass';fs.writeFileSync('hearframe-grand-v4/rendered/live-qa.json',JSON.stringify(results,null,2));console.log(JSON.stringify(results,null,2));if(failed)process.exitCode=1;
